Hash map from value → index. O(n) time, O(n) space.
```js
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
}
```

```js
function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const c = new Array(26).fill(0);
  for (const ch of s) c[ch.charCodeAt(0) - 97]++;
  for (const ch of t) if (--c[ch.charCodeAt(0) - 97] < 0) return false;
  return true;
}
```
Alt: sort both — O(n log n).

```js
function isPalindrome(s) {
  let l = 0, r = s.length - 1;
  const ok = c => /[a-z0-9]/i.test(c);
  while (l < r) {
    while (l < r && !ok(s[l])) l++;
    while (l < r && !ok(s[r])) r--;
    if (s[l].toLowerCase() !== s[r].toLowerCase()) return false;
    l++; r--;
  }
  return true;
}
```
Two pointers, O(n) time, O(1) space.

```js
function maxProfit(prices) {
  let min = Infinity, best = 0;
  for (const p of prices) {
    min = Math.min(min, p);
    best = Math.max(best, p - min);
  }
  return best;
}
```
O(n) single pass.

```js
function hasDup(nums) {
  return new Set(nums).size !== nums.length;
}
```

```js
function moveZeroes(nums) {
  let w = 0;
  for (let r = 0; r < nums.length; r++) {
    if (nums[r] !== 0) [nums[w], nums[r]] = [nums[r], nums[w]], w++;
  }
}
```
