```js
function firstUniqChar(s) {
  const c = {};
  for (const ch of s) c[ch] = (c[ch] || 0) + 1;
  for (let i = 0; i < s.length; i++) if (c[s[i]] === 1) return i;
  return -1;
}
```

```js
function isValid(s) {
  const pair = { ')': '(', ']': '[', '}': '{' };
  const st = [];
  for (const c of s) {
    if ('([{'.includes(c)) st.push(c);
    else if (st.pop() !== pair[c]) return false;
  }
  return st.length === 0;
}
```
Codility Lesson 7: Brackets.

```js
function merge(a, b) {
  const r = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) r.push(a[i] <= b[j] ? a[i++] : b[j++]);
  return [...r, ...a.slice(i), ...b.slice(j)];
}
```

```js
function rotate(A, K) {
  if (A.length === 0) return A;
  K = K % A.length;
  return A.slice(-K).concat(A.slice(0, -K));
}
```

```js
function missing(A) {
  const N = A.length + 1;
  const expected = N * (N + 1) / 2;
  return expected - A.reduce((s, x) => s + x, 0);
}
```
