```js
function jumps(X, Y, D) { return Math.ceil((Y - X) / D); }
```

```js
function reverse(head) {
  let prev = null, cur = head;
  while (cur) {
    const next = cur.next;
    cur.next = prev;
    prev = cur;
    cur = next;
  }
  return prev;
}
```

```js
function depth(node) {
  if (!node) return 0;
  return 1 + Math.max(depth(node.left), depth(node.right));
}
```

```js
function reverse(s) {
  let l = 0, r = s.length - 1;
  while (l < r) [s[l++], s[r--]] = [s[r], s[l]];
}
```
Careful: swap uses old values before ++/-- take effect.

```js
function groupAnagrams(strs) {
  const m = new Map();
  for (const s of strs) {
    const key = [...s].sort().join('');
    (m.get(key) || m.set(key, []).get(key)).push(s);
  }
  return [...m.values()];
}
```

```js
function productExceptSelf(nums) {
  const n = nums.length, res = new Array(n).fill(1);
  let l = 1;
  for (let i = 0; i < n; i++) { res[i] = l; l *= nums[i]; }
  let r = 1;
  for (let i = n - 1; i >= 0; i--) { res[i] *= r; r *= nums[i]; }
  return res;
}
```
Two passes, O(n) time.
